import gc

print("Checking all variables for demo data...")

for name in sorted(globals().keys()):
    obj = globals()[name]
    # Skip non-callables and None
    if obj is None or not hasattr(obj, '__iter__'):
        continue

    try:
        # Check if iterable
        t = type(obj)
        if 'str' in str(t):
            continue  # strings are fine but skip them
        if isinstance(obj, list):
            print(f"\n{name}: {type(obj)} with {len(obj)} items")
            if len(obj) < 10:
                print(f"  Content: {obj}")
            else:
                print(f"  First few: {obj[:5]}")
    except Exception as e:
        pass

print("\n\nAlso checking sys.modules for clues...")

